package library

import (
	"strconv"
	"strings"
)

// ManagedPlaylistRootName is reserved for the playlist tree generated by
// RekordLink. A source export can contain this tree after the user imports the
// merged XML into rekordbox; it must never be published as original input or
// every merge would wrap the previous merge again.
const ManagedPlaylistRootName = "RekordLink"

// StripManagedPlaylistRoots removes generated top-level playlist trees from a
// parsed source library. It does not remove collection tracks: those are
// independently content-deduplicated and may legitimately have local edits.
//
// rekordbox may add a numeric suffix when an imported folder name already
// exists, so RekordLink also owns names such as "RekordLink (2)".
func StripManagedPlaylistRoots(lib *Library) int {
	if lib == nil {
		return 0
	}
	kept, removed := originalPlaylistRoots(lib.Playlists.Root.Nodes)
	lib.Playlists.Root.Nodes = kept
	return removed
}

// StripManagedPlaylistRootsXML applies the publication boundary to raw
// rekordbox XML. Unchanged input is returned byte-for-byte so merely upgrading
// a client does not rewrite an otherwise clean snapshot.
func StripManagedPlaylistRootsXML(data []byte) ([]byte, int, error) {
	lib, err := Parse(data)
	if err != nil {
		return nil, 0, err
	}
	removed := StripManagedPlaylistRoots(lib)
	if removed == 0 {
		return data, 0, nil
	}
	out, err := Marshal(lib)
	if err != nil {
		return nil, 0, err
	}
	return out, removed, nil
}

func isManagedPlaylistRootName(name string) bool {
	name = strings.TrimSpace(name)
	if strings.EqualFold(name, ManagedPlaylistRootName) {
		return true
	}
	if len(name) <= len(ManagedPlaylistRootName) || !strings.EqualFold(name[:len(ManagedPlaylistRootName)], ManagedPlaylistRootName) {
		return false
	}
	rest := strings.TrimSpace(name[len(ManagedPlaylistRootName):])
	if len(rest) < 3 || rest[0] != '(' || rest[len(rest)-1] != ')' {
		return false
	}
	ordinal, err := strconv.Atoi(rest[1 : len(rest)-1])
	return err == nil && ordinal > 0
}

func originalPlaylistRoots(nodes []Node) ([]Node, int) {
	kept := make([]Node, 0, len(nodes))
	removed := 0
	for _, node := range nodes {
		if node.Type == "0" && isManagedPlaylistRootName(node.Name) {
			removed++
			continue
		}
		kept = append(kept, node)
	}
	return kept, removed
}
